import json
d=json.load(open('des125_vec.json'))
def flat(p): return [int(round(v*2)) for xy in p for v in xy]
regs=[[r['c'],flat(r['p'])]+[flat(h) for h in r['h']] for r in d['regions']]
strokes=[[flat(P),[int(round(w*2)) for w in Wd]] for P,Wd in d['strokes']]
outl=[flat(o) for o in d['outline']]
js=["// The designer at 125.0 s, measured on the source frame (frame px x2, integers): flat colour regions (posterized,",
"// simplified polygons with holes; colours pre-grade), ink strokes (skeleton polylines + measured widths) and the outer",
"// outline. Generated by snapshots/s27-meas/export_des.py. Redrawn by code in designer.js.",
"export const DES_REGIONS = "+json.dumps(regs,separators=(',',':'))+";",
"export const DES_STROKES = "+json.dumps(strokes,separators=(',',':'))+";",
"export const DES_OUTLINE = "+json.dumps(outl,separators=(',',':'))+";"]
open('/Users/computer/rootline/apprentice-film/src/shots/s27/designerData.js','w').write("\n".join(js)+"\n")
import os; print(os.path.getsize('/Users/computer/rootline/apprentice-film/src/shots/s27/designerData.js'))
